namespace tvlist {

const char* const* regions(int& count)
{
    count = (int)(sizeof(kRegions) / sizeof(kRegions[0]));
    return kRegions;
}

QString regionTitleKey(const QString& regionKey)
{
    return qFromUtf8("tv.region.") + regionKey;
}

const std::vector<TvChannel>& stations()
{
    static const std::vector<TvChannel> s(
        kChannels, kChannels + sizeof(kChannels) / sizeof(kChannels[0]));
    return s;
}

std::vector<TvChannel> byRegion(const QString& regionKey)
{
    std::vector<TvChannel> out;
    for (size_t i = 0; i < stations().size(); ++i)
        if (regionKey.isEmpty() || regionKey == stations()[i].region)
            out.push_back(stations()[i]);
    return out;
}

} // namespace tvlist
